import { _decorator, Component, find } from 'cc';
import { Socket } from './Socket';
const { ccclass } = _decorator;

@ccclass('_TempGuideTest')
export class _TempGuideTest extends Component {
    setTarget() {
        const t = find('GuideTestTarget');
        if (t) Socket.activeGuideTarget = t;
    }
    clearTarget() {
        Socket.activeGuideTarget = null;
    }
}
